<template>
  <div class="page"><el-card shadow="never"><div class="toolbar"><span>角色</span><el-select v-model="selected" style="width:200px"><el-option v-for="x in roles" :key="x.role.id" :label="x.role.name" :value="x.role.id"/></el-select><el-button type="primary" @click="save">保存权限</el-button></div><el-tree ref="tree" :data="treeData" node-key="id" show-checkbox default-expand-all :props="{label:'name',children:'children'}"/></el-card></div>
</template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{systemApi}from'@/api/system';import type{Permission,RoleView}from'@/api/system';const roles=ref<RoleView[]>([]),permissions=ref<Permission[]>([]),selected=ref<number>(),tree=ref<any>();const current=computed(()=>roles.value.find(x=>x.role.id===selected.value));const treeData=computed(()=>{const roots=permissions.value.filter(x=>!x.parentId);return roots.map(x=>({...x,children:permissions.value.filter(y=>y.parentId===x.id)}))});function sync(){if(current.value)tree.value?.setCheckedKeys(current.value.permissionIds)}async function init(){roles.value=await systemApi.roles();permissions.value=await systemApi.permissions();selected.value=roles.value[0]?.role.id;setTimeout(sync)}async function save(){if(!current.value)return;try{await systemApi.updateRole(current.value.role.id,{name:current.value.role.name,remark:current.value.role.remark,permissionIds:tree.value.getCheckedKeys(false)});ElMessage.success('权限已保存');roles.value=await systemApi.roles();sync()}catch{}}onMounted(init)</script><style scoped>.toolbar{display:flex;align-items:center;gap:12px;margin-bottom:18px}</style>
